---@class BindGearHint2Interrupter
---@field gearHintBehaviour     Engine.Modules.LuaBehaviour
---@field interrupter           ElectricalSystem.ElectricalSwitch.Interrupter
local BindGearHint2Interrupter = Class('BindGearHint2Interrupter')
-- 外部调用时使用:
-- local BindGearHint2Interrupter = import('Game.DreamSpace.Level1.BindGearHint2Interrupter')

-- ========================================================

--- 将 GearHint 和 interrupter 绑定起来;
--- 每当玩家点击 GearHint ui 按钮, 就会触发 interrupter 的对应函数, 模拟 interrupter 被触发;

--- 改: 为了能先完整地播放完 "开启开关" 的动画, 然后再接通电路, 本代码做了修改...


--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程

local GearHint = import('Game.DreamSpace.Hint.GearHint')

local DreamSpaceLuaUtils = import('Game.DreamSpace.Tools.DreamSpaceLuaUtils')

---@type DreamSpaceStates
local DreamSpaceStates = import('Game.DreamSpace.Tools.DreamSpaceStates')

---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject


--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
local Vector3 = CS.UnityEngine.Vector3

local DreamSpaceUtils = CS.DreamSpace.DreamSpaceUtils


local Interrupter = CS.ElectricalSystem.ElectricalSwitch.Interrupter
local LuaBehaviour = CS.Engine.Modules.LuaBehaviour

local OnOff = CS.Game.OnOff



-- ========================================================

local isDisposable = true -- 本机关是否为一次性的

-- ========================================================



function BindGearHint2Interrupter:__init()
    self.controller = nil

    self.DoBeforeTriggerInterrupter = nil -- 协程函数指针, 比如 "开关被开启" 动画的完整播放
end


function BindGearHint2Interrupter:__delete()
    self.co_1 = nil
    self.co_2 = nil
end



function BindGearHint2Interrupter:Awake()
    KTool.SetActive(self.controller.gameObject, true)
end

function BindGearHint2Interrupter:Start()
    KTool.SetActive(self.controller.gameObject, true)

    assert( self.gearHintBehaviour )
    if isNull(self.interrupter) then 
        self.interrupter = KTool.GetComponent(self.controller.gameObject, typeof(Interrupter))
    end 
    assert( self.interrupter )

    --self.interrupter = KTool.GetComponent(self.controller.gameObject, typeof(Interrupter))
    --assert( self.interrupter )

    self.gearHint = DreamSpaceLuaUtils.GetLuaScr(self.gearHintBehaviour.gameObject, "Game.DreamSpace.Hint.GearHint" )
    self.isButtonPressed = false
    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = cs_coroutine.start(self.DelayInit, self)
end




function BindGearHint2Interrupter:DelayInit() 

    coroutine.yield(Yielders.EndOfFrame)
    while self.interrupter.isInit == false do 
        coroutine.yield(Yielders.EndOfFrame)
    end

    -- -- 只尝试有限次;
    for i=1,DreamSpaceStates.DelayInitWaitFrames do
        if self.gearHint.isInit == true then
            self.gearHint:BindHintButton( Bind(self,self.WhenPressButton) )
            return
        end 
        coroutine.yield(Yielders.EndOfFrame)
    end 
    printError( "始终没等到 gearHint 初始化完成, 请查看 gearHint 是否存在异常" )
end


function BindGearHint2Interrupter:OnDestroy()
    DreamSpaceLuaUtils.StopCoroutine( self.co )
    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    DreamSpaceLuaUtils.StopCoroutine( self.co_2 )
    self.co = nil 
    self.co_1 = nil 
    self.co_2 = nil 

    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


-- -- ===============================================================


function BindGearHint2Interrupter:WhenPressButton() 

    if self.isButtonPressed == false then
        self.isButtonPressed = true

        DreamSpaceLuaUtils.StopCoroutine( self.co )
        self.co = cs_coroutine.start(function()

            
            -- todo: 放在这里比较脏: 禁止玩家 (猫移动 + 旋转视角):
            DreamSpaceStates.LockInput_ByCount( DreamSpaceStates.InputLockState.Lock ) -- 希望禁止玩家输入
            DreamSpaceStates.LockSubPanelFreeInPC_ByCount( DreamSpaceStates.InputLockState.Lock ) -- PC 版 禁止打开 ui 子界面 
            print("koko - gearhint ui 锁 - 禁用")
            
            -- 正式触发电路前的工作
            if self.DoBeforeTriggerInterrupter ~= nil then 
                cs_coroutine.yield_return( self.DoBeforeTriggerInterrupter() )
            end 
            
            -- 
            self.interrupter:RunOnTriggerEnter()
            --self:RunOnTriggerEnter__( self.interrupter ) -- todo: 可能要把 Interrupter lua 化

            DreamSpaceLuaUtils.StopCoroutine( self.co_2 )
            self.co_2 = cs_coroutine.start(self.DelayExit, self)

        end)        
    end
end


function BindGearHint2Interrupter:DelayExit() 

    -- 延迟数帧后 exit, 让效果逼真一些:
    coroutine.yield(Yielders.EndOfFrame)
    coroutine.yield(Yielders.EndOfFrame)
    coroutine.yield(Yielders.EndOfFrame)
    self.interrupter:RunOnTriggerExit()

    -- 一次性机关需要立刻清理掉:
    if isDisposable then
    
        coroutine.yield(Yielders.EndOfFrame)
        coroutine.yield(Yielders.EndOfFrame)
        coroutine.yield(Yielders.EndOfFrame)
        self.gearHint:SetIsActive(false)
    end

    -- 确保 触发机关引发的 ui子界面锁, 能坚持到 对应的 timeline 播放 (此时, timeline 的锁会接力)...
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 0.5 ))

    DreamSpaceStates.LockInput_ByCount( DreamSpaceStates.InputLockState.Unlock ) -- 解除禁止:玩家输入
    DreamSpaceStates.LockSubPanelFreeInPC_ByCount( DreamSpaceStates.InputLockState.Unlock ) -- PC 版 允许打开 ui 子界面 
    print("koko - gearhint ui 锁 - 允许")

    self.isButtonPressed = false;
end



function BindGearHint2Interrupter:RunOnTriggerEnter__( interrupter_) 

    if interrupter_.isActive == false then
    
        return
    end 

    assert( isNotNull( interrupter_.isLastFrameSwitchOn ) )

    
    interrupter_.electricalTrigger:UpdateStatesWhenBeTriggeed( interrupter_.isLastFrameSwitchOn )
    interrupter_.isLastFrameSwitchOn = interrupter_.electricalTrigger.isSwitchOn

    if isNotNull( interrupter_.WhenOnTriggerEnter ) then
    
        interrupter_.WhenOnTriggerEnter()
    end


end





return BindGearHint2Interrupter
